response.body:
@charset "UTF-8";
@import url("https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@300;400;500;700;900&display=swap");

html,
body {
    height: 100%;
}

body {
    -webkit-text-size-adjust: 100%;
    padding: 0;
    margin: 0;
    font-family: "Noto Sans JP", sans-serif;
    font-feature-settings: "palt" 1;
    -webkit-font-feature-settings: "palt" 1;
    -webkit-font-smoothing: antialiased;
    letter-spacing: 0.02em;
    color: #333;
}

/* default */

div,
dl,
dt,
dd,
ul,
ol,
li,
h1,
h2,
h3,
h4,
h5,
h6,
pre,
code,
form,
fieldset,
legend,
input,
textarea,
p,
blockquote,
th,
td {
    margin: 0;
    padding: 0;
}

table {
    border-collapse: collapse;
    border-spacing: 0;
    word-break: break-all;
    font-size: inherit;
    width: 100%;
}

fieldset,
img {
    border: 0;
}

address,
caption,
cite,
code,
dfn,
em,
strong,
th,
var {
    font-style: normal;
    font-weight: normal;
}

li {
    list-style: none;
}

caption,
th {
    text-align: left;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    font-size: 100%;
    font-weight: normal;
}

q::before,
q::after {
    content: "";
}

abbr {
    border: 0;
    font-variant: normal;
}

sup {
    vertical-align: text-top;
}
sub {
    vertical-align: text-bottom;
}

input,
textarea,
select {
    font-family: inherit;
    font-size: inherit;
    font-weight: inherit;
}

input,
textarea,
select {
    *font-size: 100%;
}

legend {
    color: #333;
}

select,
input,
button,
textarea {
    font: 99% arial, helvetica, clean, sans-serif;
}

pre,
code,
kbd,
samp {
    font-family: monospace;
    *font-size: 108%;
    line-height: 100%;
}

.aligncenter {
    text-align: center;
}

figure {
    padding: 0;
    margin: 0;
}

img {
    vertical-align: bottom;
    line-height: 1;
    max-width: 100%;
    height: auto;
}

input[type="submit"],
input[type="button"] {
    border-radius: 0;
    -webkit-box-sizing: content-box;
    -webkit-appearance: button;
    appearance: button;
    border: none;
    box-sizing: border-box;
    cursor: pointer;
}

input[type="submit"]::-webkit-search-decoration,
input[type="button"]::-webkit-search-decoration {
    display: none;
}

input[type="submit"]::focus,
input[type="button"]::focus {
    outline-offset: -2px;
}

a {
    text-decoration: none;
    color: #333;
    transition: all 0.25s ease;
}

a:hover {
}

* {
    box-sizing: border-box;
}

/* color

text1 #333
text2 #808080
border #707070

gray #f2f2f2

*/

/* common item ---------------------------------------*/

.clearfix::after,
.inner::after {
    visibility: hidden;
    display: block;
    font-size: 0;
    content: " ";
    clear: both;
    height: 0;
}

@media all and (-ms-high-contrast: none) {
    *::-ms-backdrop,
    .foo {
        color: red;
    }

    /* IE11 */
}

@media all and (-ms-high-contrast: none) {
    .foo {
        color: green;
    }

    /* IE10〜Edge */
}

/* layout ---------------------------------------*/

.wrapper {
    padding: 0 30px;
}
.wrapper-photo {
    padding: 0;
}

.inner {
    max-width: 976px;
    margin: 0 auto;
}

.section {
    margin-bottom: 50px;
}
.ov-h {
    overflow: hidden;
}
.overlay {
    display: none;
}

/* header ---------------------------------------*/

header {
    position: relative;
    height: 210px;
    padding: 70px 0 0;
    z-index: 100;
}

.header-logo {
    overflow: hidden;
    position: absolute;
    left: 0px;
    top: 20px;
}

.header-top {
    position: fixed;
    left: 0;
    top: 0;
    width: 100%;
    height: 70px;
    background: rgba(255, 255, 255, 0.9);
    z-index: 100;
    padding: 0 30px;
}

.header-inner {
    max-width: 976px;
    height: 100%;
    margin: 0 auto;
    position: relative;
}

#openmenu {
    display: block;
    width: 24px;
    height: 24px;
    text-indent: -99em;
    overflow: hidden;
    position: absolute;
    right: 0px;
    top: 15px;
    cursor: pointer;
}

#openmenu span {
    content: "";
    display: block;
    width: 25px;
    height: 1px;
    background: #333;
    position: absolute;
    left: 0px;
    transition: all 0.25s ease;
}

#openmenu span:nth-child(1) {
    top: 4px;
}
#openmenu span:nth-child(2) {
    top: 11px;
}
#openmenu span:nth-child(3) {
    top: 18px;
}

#openmenu.is-open span:nth-child(1) {
    transform: rotate(45deg);
    top: 10px;
    left: 2px;
}

#openmenu.is-open span:nth-child(2) {
    opacity: 0;
    left: -25px;
}

#openmenu.is-open span:nth-child(3) {
    transform: rotate(-45deg);
    top: 10px;
    left: 2px;
}

.header-nav-wrapper {
    position: absolute;
    left: 0;
    bottom: 0;
    width: 100%;
    padding: 0 30px;
}

.header-nav {
    max-width: 976px;
    margin: 0 auto;
    position: relative;
}

.header-nav-list {
    font-size: 0px;
}

.header-nav-list li {
    display: inline-block;
    font-size: 14px;
}

.header-nav-list li a {
    display: block;
    padding: 20px 15px;
    line-height: 1;
}

.header-nav-list li a:hover {
    text-decoration: underline;
}

.header-nav-list li:first-child a {
    padding-left: 0;
}

.header-search {
    position: absolute;
    right: 0;
    top: 50%;
    transform: translate(0, -50%);
    width: 160px;
    border: 1px solid #707070;
    border-radius: 20px;
    overflow: hidden;
}

.header-search input {
    font-size: 14px;
    border: none;
    line-height: 1;
    padding: 9px 15px 9px 40px;
    width: 100%;
    background: none;
    outline: none;
}

.header-search button {
    background: none;
    padding: 0;
    border: none;
    cursor: pointer;
    position: absolute;
    left: 17px;
    top: 50%;
    transform: translate(0, -60%);
}

/* gnav ---------------------------------------*/

.gnav {
    position: fixed;
    left: 0;
    top: 0;
    width: 100%;
    height: 250px;
    transition: all 0.25s ease;
    background: #fff;
    transform: translate3d(0, -100%, 0);
    z-index: 90;
    box-shadow: 0px 0px 25px rgba(0, 0, 0, 0.2);
    padding: 80px 30px 0;
}

.gnav.is-active {
    transform: translate3d(0, 0, 0);
    opacity: 1;
}

.gnav-inner {
    max-width: 976px;
    margin: 0 auto;
    position: relative;
}

.gnav-list {
    position: relative;
    font-size: 0px;
}

.gnav-list li {
    display: inline-block;
    font-size: 14px;
}

.gnav-list li a {
    display: block;
    padding: 20px 18px;
    line-height: 1;
}

.gnav-list li a:hover {
    text-decoration: underline;
}

.gnav-list li:first-child a {
    padding-left: 0;
}

.gnav-list li.gnav-logout {
    position: absolute;
    right: 0;
    top: 15px;
}

.gnav-list li.gnav-logout a {
    text-align: center;
    display: inline-block;
    color: #fff;
    font-size: 12px;
    line-height: 1.3;
    padding: 5px 15px 6px;
    background: #808080;
    border-radius: 20px;
    margin-right: 5px;
    margin-bottom: 5px;
    text-decoration: none;
    transition: all 0.25s ease;
    width: 100px;
}

.gnav-list li.gnav-logout a:hover {
    opacity: 0.7;
}

.gnav-search {
    width: 380px;
    background: #f2f2f2;
    border-radius: 8px;
    position: relative;
    overflow: hidden;
    margin-bottom: 30px;
}

.gnav-search input {
    font-size: 13px;
    border: none;
    line-height: 1;
    padding: 11px 25px;
    background: none;
    outline: none;
}

.gnav-search button {
    background: none;
    padding: 0;
    border: none;
    cursor: pointer;
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translate(0, -60%);
}

/* footer ---------------------------------------*/

footer {
    padding: 30px 0 50px 0;
    background: #f2f2f2;
}

.footer-inner {
    max-width: 1100px;
    margin: 0 auto;
    position: relative;
}

.footernav {
}
.footernav-list {
    display: flex;
    justify-content: center;
    align-items: center;
    flex-wrap: wrap;
}

.footernav-list li {
    font-size: 14px;
}

.footernav-list li a {
    display: block;
    padding: 20px 25px;
    line-height: 1;
    color: #333;
}

.footernav-list li a:hover {
    text-decoration: underline;
}

/* login ---------------------------------------*/

.login {
    max-width: 330px;
    margin: 0 auto;
}

.login-form {
}

.login-form-content {
    margin-top: 30px;
}
.login-form-content label {
    line-height: 1;
