/* title ---------------------------------------*/

.title-site {
    font-weight: 700;
    font-size: 60px;
    line-height: 1;
    text-align: center;
}

.title-page {
    font-weight: 700;
    font-size: 40px;
    line-height: 1.5;
}

.title-section {
    font-weight: 700;
    font-size: 44px;
    line-height: 1.5;
    letter-spacing: -0.02em;
}

.title-block {
    font-weight: 700;
    font-size: 36px;
    line-height: 1.5;
}

.title-paragraph {
    font-weight: 700;
    font-size: 28px;
    line-height: 1.5;
}

.title-small {
    font-weight: 700;
    font-size: 18px;
    line-height: 1.5;
}

.title-bar {
    font-size: 18px;
    font-weight: bold;
    line-height: 1.5;
    background: #f2f2f2;
    padding: 5px 20px 6px;
}

/* text ---------------------------------------*/

.text-center {
    text-align: center !important;
}
.text-right {
    text-align: right !important;
}
.text-left {
    text-align: left !important;
}

.text-s {
    font-size: 1.2rem;
    line-height: 1.5;
}

.text-m {
    font-size: 1.4rem;
    line-height: 1.5;
}

.text-l {
    font-size: 1.8rem;
    color: #484848;
    line-height: 1.94;
}

.text-bold {
    font-weight: 600;
}

.text-red {
    color: #aa0000 !important;
}

.text-ellipsis-2 {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    overflow: hidden;
}

.text-ellipsis-3 {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    overflow: hidden;
}

.text-ellipsis-4 {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 4;
    overflow: hidden;
}

@media all and (-ms-high-contrast: none) {
    .text-ellipsis-2 {
        height: 3.2em;
    }

    /* IE10〜Edge */
    .text-ellipsis-3 {
        height: 4.7em;
    }

    /* IE10〜Edge */
}

.text-ellipsis-count::after {
    content: "…";
}

.text-link {
    color: #597ea6;
}

.text-link:hover {
    text-decoration: underline;
}

/* -------------------- pankuzu --------------------- */

.pankuzu {
    padding: 50px 0;
}

.pankuzu-list {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    display: block;
}

.pankuzu-list > li {
    display: inline;
    font-size: 14px;
    margin-right: 10px;
}

.pankuzu-list > li:last-child {
    margin-right: 0;
}

.pankuzu-list > li a,
.pankuzu-list > li span {
    padding: 0px 15px 0px 0px;
    position: relative;
}

.pankuzu-list > li a {
    text-decoration: none;
}

.pankuzu-list > li a::after {
    display: block;
    content: "";
    width: 8px;
    height: 8px;
    border-top: 1px solid #939393;
    border-right: 1px solid #939393;
    transform: rotate(45deg) translate(0, -50%);
    position: absolute;
    right: 0px;
    top: 45%;
}

.pankuzu-list > li a:hover {
    color: #939393;
    text-decoration: underline;
}

.pankuzu-list > li span {
}

/* bg ---------------------------------------*/

.bg-gray {
    background: #f2f2f2;
}

/* indexmenu ---------------------------------------*/

.indexmenu {
    padding: 40px 30px 30px;
}

.indexmenu-list-wrapper {
}

.indexmenu-list {
    display: flex;
    justify-content: flex-start;
    flex-wrap: wrap;
    gap: 20px;
}

.indexmenu-list > li {
    width: calc(33.3333% - 15px);
}

.indexmenu-list > li:nth-child(3n + 1) {
    margin-left: 0;
}

.indexmenu-list-item {
    display: block;
    text-align: center;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 15px 15px;
    transition: all 0.25s ease;
    height: 100%;
    position: relative;
    overflow: hidden;
}

.indexmenu-list-item:hover {
    background-color: #fafafa;
    box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.1);
}

.indexmenu-list-item::after {
    content: "";
    display: block;
    position: absolute;
    right: 0;
    bottom: 0;
    border-left: 35px transparent solid;
    border-top: 35px transparent solid;
    border-bottom: 35px #808080 solid;
    transition: all 0.25s ease;
}

.indexmenu-list-item:hover::after {
    border-bottom: 35px #333 solid;
}

.indexmenu-item-image {
    display: inline-block;
    background: #f2f2f2;
    border-radius: 50%;
    width: 60px;
    height: 60px;
    position: relative;
}

.indexmenu-item-image img {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
}

.indexmenu-item-body {
    padding-top: 5px;
}

.indexmenu-item-body h3 {
    font-weight: 700;
    font-size: 22px;
    line-height: 1.5;
    margin-bottom: 5px;
}

.indexmenu-item-body p {
    color: #808080;
    font-size: 14px;
    line-height: 1.6;
}

.indexmenu-item-btn {
    width: 144px;
    text-align: center;
    display: inline-block;
    color: #fff;
    font-size: 14px;
    line-height: 1.3;
    padding: 9px;
    background: #333;
    border-radius: 20px;
}

.indexmenu-list-item .arrow {
    content: "";
    display: block;
    position: absolute;
    right: 0;
    bottom: 0;
    width: 20px;
    height: 20px;
    z-index: 5;
}

.indexmenu-list-item .arrow::before {
    display: block;
    content: "";
    background: #fff;
    background-size: 100%;
    width: 4px;
    height: 1px;
    position: absolute;
    left: 11px;
    top: 8px;
    transform: translate(0, -50%) rotate(45deg);
}

.indexmenu-list-item .arrow::after {
    display: block;
    content: "";
    background: #fff;
    background-size: 100%;
    width: 10px;
    height: 1px;
    position: absolute;
    left: 5px;
    top: 10px;
    transform: translate(0, -50%);
}

/* newslist ---------------------------------------*/

.news-list-wrapper {
}
.news-list {
}
.news-list > li {
    margin-top: 32px;
}

.news-item {
    display: flex;
    justify-content: flex-start;
}

.news-item-date {
    display: inline-block;
    color: #808080;
    font-size: 14px;
    line-height: 1.2;
    width: 110px;
    padding-top: 5px;
}

.news-item-category {
    width: 112px;
    text-align: center;
    display: inline-block;
    color: #fff;
    font-size: 12px;
    line-height: 1.1;
    padding: 5px 5px 6px;
    background: #333;
    border-radius: 20px;
    margin-right: 10px;
    height: 100%;
    margin-top: 2px;
}

.news-item-title {
    font-size: 16px;
    color: #333;
    transition: all 0.25s ease;
    width: calc(100% - 240px);
    line-height: 1.75;
}

.news-item-title:hover {
    text-decoration: underline;
}

.news-more {
    text-align: center;
    margin-top: 30px;
}

.news-more-index {
    text-align: right;
    margin-top: 30px;
    font-size: 14px;
}

/* panel ---------------------------------------*/

.panel {
}
.panel-list {
    display: flex;
    flex-wrap: wrap;
}
.panel-list > li {
    width: calc(33.333% - 14px);
    margin: 0 0 60px 20px;
}

.panel-list > li:nth-child(3n + 1) {
    margin-left: 0;
}

.panel-list > li a {
    display: block;
    transition: all 0.25s ease;
}

.panel-list > li a:hover {
    opacity: 0.7;
}

.panel-item-image {
    border: 1px solid #cccccc;
    border-radius: 8px;
    overflow: hidden;
    padding-bottom: 50%;
    height: 0;
    position: relative;
}

.panel-item-image img {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    max-width: 100%;
}

.panel-item-body {
    padding-top: 20px;
}

.panel-item-category {
    display: block;
    margin-bottom: 10px;
}

@media screen and (min-width: 769px) {
    .panel-item-category {
