    -webkit-appearance: none;
    outline: none;
    border-radius: 8px;
    line-height: 1;
    background: url("../img/common/select.svg") no-repeat right 10px top 50%
        #f2f2f2;
    background-size: 11px;
}

.is-selected {
    color: #000;
}

select::-ms-expand {
    display: none;
}

.form-text {
    font-size: 16px;
    padding: 10px 13px;
    background: #f2f2f2;
    border: 1px solid #f2f2f2;
    width: 100%;
    box-sizing: border-box;
    -webkit-appearance: none;
    outline: none;
    border-radius: 8px;
}

.form-radio {
    display: inline-block;
    line-height: 1;
    margin-right: 5px;
    font-size: 14px;
    position: relative;
}

.form-radio label {
    box-sizing: border-box;
    cursor: pointer;
    display: inline-block;
    line-height: 1.4;
    min-height: 23px;
    margin: 0px 0;
    padding: 3px 0 0 25px;
    position: relative;
    vertical-align: top;
}

.form-radio input[type="radio"] {
    position: absolute;
    left: 0px;
    top: 0px;
    width: 1px;
    height: 1px;
    overflow: hidden;
    opacity: 0;
}

.form-radio label::before {
    display: block;
    content: "";
    border: 1px solid #aaa;
    border-radius: 50%;
    width: 20px;
    height: 20px;
    position: absolute;
    left: 0;
    top: 50%;
    transform: translate(0, -50%);
}

.form-radio input:checked + label::after {
    display: block;
    content: "";
    background: #2a619b;
    border-radius: 50%;
    width: 14px;
    height: 14px;
    position: absolute;
    left: 4px;
    top: 50%;
    transform: translate(0, -50%);
}

.form-radio input:disabled + label {
    opacity: 0.7;
}

.form-checkbox {
    display: inline-block;
    line-height: 1;
    margin-right: 5px;
    font-size: 14px;
    position: relative;
}

.form-checkbox label {
    box-sizing: border-box;
    cursor: pointer;
    display: inline-block;
    line-height: 1.4;
    min-height: 23px;
    margin: 0px 0;
    padding: 3px 0 0 30px;
    position: relative;
    vertical-align: top;
}

.form-checkbox input[type="checkbox"] {
    position: absolute;
    left: 0px;
    top: 0px;
    width: 1px;
    height: 1px;
    overflow: hidden;
    opacity: 0;
}

.form-checkbox label::before {
    display: block;
    content: "";
    border: none;
    background: #f2f2f2;
    border-radius: 2px;
    width: 20px;
    height: 20px;
    position: absolute;
    left: 0;
    top: 50%;
    transform: translate(0, -50%);
}

.form-checkbox input:checked + label::after {
    display: block;
    content: "";
    width: 5px;
    height: 8px;
    border-right: 2px solid #333;
    border-bottom: 2px solid #333;
    position: absolute;
    left: 7px;
    top: 45%;
    transform: translate(0, -50%) rotate(40deg);
}

.form-checkbox input:disabled + label {
    opacity: 0.7;
}

.form-textarea {
    padding: 13px 5px;
    border: 1px solid #999;
    width: 100%;
    box-sizing: border-box;
    height: 80px;
    -webkit-appearance: none;
    outline: none;
    border-radius: 0;
}

::placeholder {
    color: #ccc;
}

.toggle-switch {
    position: relative;
    width: 60px;
    height: 30px;
    margin: auto;
    display: inline-block;
}

.toggle-input {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    z-index: 5;
    opacity: 0;
    cursor: pointer;
}

.toggle-switch label {
    width: 60px;
    height: 30px;
    background: #ccc;
    position: relative;
    display: inline-block;
    border-radius: 30px;
    transition: 0.1s;
    box-sizing: border-box;
}

.toggle-switch label::after {
    content: "";
    position: absolute;
    width: 30px;
    height: 30px;
    border-radius: 100%;
    left: 0;
    top: 0;
    z-index: 2;
    background: #fff;
    box-shadow: 0 0 5px rgba(0, 0, 0, 0.2);
    transition: 0.1s;
}

.toggle-input:checked + label {
    background-color: #4bd865;
}

.toggle-input:checked + label::after {
    left: 30px;
}

.must {
    color: #aa0000;
}

/* accordion ---------------------------------------*/

.accordion {
}

.accordion-title {
    position: relative;
