}

.accordion-title::after {
    display: block;
    content: "";
    border-bottom: 3px solid #2a619b;
    border-right: 3px solid #2a619b;
    width: 10px;
    height: 10px;
    margin-top: -17px;
    position: absolute;
    right: 10px;
    top: 50%;
    transform: rotate(45deg);
    transition: all 0.25s ease;
}

.accordion-title.is-open::after {
    transform: rotate(225deg);
}

.accordion-body {
    display: none;
}

