/* indexmenu ---------------------------------------*/

.indexmenu {
    padding: 40px 30px 30px;
}

.indexmenu-list-wrapper {
}

.indexmenu-list {
    display: flex;
    justify-content: flex-start;
    flex-wrap: wrap;
    gap: 20px;
}

.indexmenu-list > li {
    width: calc(33.3333% - 15px);
}

.indexmenu-list > li:nth-child(3n + 1) {
    margin-left: 0;
}

.indexmenu-list-item {
    display: block;
    text-align: center;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 15px 15px;
    transition: all 0.25s ease;
    height: 100%;
    position: relative;
    overflow: hidden;
}

.indexmenu-list-item:hover {
    background-color: #fafafa;
    box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.1);
}

.indexmenu-list-item::after {
    content: "";
    display: block;
    position: absolute;
    right: 0;
    bottom: 0;
    border-left: 35px transparent solid;
    border-top: 35px transparent solid;
    border-bottom: 35px #808080 solid;
    transition: all 0.25s ease;
}

.indexmenu-list-item:hover::after {
    border-bottom: 35px #333 solid;
}

.indexmenu-item-image {
    display: inline-block;
    background: #f2f2f2;
    border-radius: 50%;
    width: 60px;
    height: 60px;
    position: relative;
}

.indexmenu-item-image img {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
}

.indexmenu-item-body {
    padding-top: 5px;
}

.indexmenu-item-body h3 {
    font-weight: 700;
    font-size: 22px;
    line-height: 1.5;
    margin-bottom: 5px;
}

.indexmenu-item-body p {
    color: #808080;
    font-size: 14px;
    line-height: 1.6;
}

.indexmenu-item-btn {
    width: 144px;
    text-align: center;
    display: inline-block;
    color: #fff;
    font-size: 14px;
    line-height: 1.3;
    padding: 9px;
    background: #333;
    border-radius: 20px;
}

.indexmenu-list-item .arrow {
    content: "";
    display: block;
    position: absolute;
    right: 0;
    bottom: 0;
    width: 20px;
    height: 20px;
    z-index: 5;
}

.indexmenu-list-item .arrow::before {
    display: block;
    content: "";
    background: #fff;
    background-size: 100%;
    width: 4px;
    height: 1px;
    position: absolute;
    left: 11px;
    top: 8px;
    transform: translate(0, -50%) rotate(45deg);
}

.indexmenu-list-item .arrow::after {
    display: block;
    content: "";
    background: #fff;
    background-size: 100%;
    width: 10px;
    height: 1px;
    position: absolute;
    left: 5px;
    top: 10px;
    transform: translate(0, -50%);
}

