/* -------------------- entry --------------------- */

.entry-wrapper {
    display: flex;
    justify-content: space-between;
}

.entry-main {
    width: calc(100% - 260px);
}

.entry-head {
    margin-bottom: 30px;
}

.entry-date {
    font-size: 14px;
    color: #808080;
    margin-bottom: 10px;
}

.entry-title {
    font-size: 30px;
    font-weight: bold;
    line-height: 1.5;
}

.entry-category {
    padding: 0;
}

.entry-category span {
    text-align: center;
    display: inline-block;
    color: #fff;
    font-size: 12px;
    line-height: 1.3;
    padding: 5px 15px 6px;
    background: #333;
    border-radius: 20px;
    margin-right: 5px;
}

.entry-inquiry {
}

.entry-inquiry a {
    text-align: center;
    display: inline-block;
    color: #fff;
    font-size: 12px;
    line-height: 1.3;
    padding: 5px 15px 6px;
    background: #09187a;
    border-radius: 20px;
    margin-right: 5px;
}

.entry-inquiry a:hover {
    text-decoration: none;
    opacity: 0.8;
}

.entry-like {
    position: relative;
    top: -10px;
    height: 40px;
}

.entry-member {
    margin: 12px 0;
    padding: 2px 20px;
    background-color: #f2f2f2
}

.entry-profile {
    display: flex;
    gap: 18px;
    margin: 8px 0;
}

.entry-profile-left {
    width: 100px;
}

.entry-profile-name {
    margin-top: 6px;
    text-align: center;
    font-size: 9px;
    line-height: 1.5;
}

.entry-profile-right {
    color: #2c2a2a;
    font-size: 12px;
    padding: 2px 6px;
    width: 100%;
}

.entry-body {
    font-size: 16px;
    line-height: 1.8;
    padding-bottom: 56px;
    word-break: break-all;
    overflow: hidden;
}

.entry-body > div {
    margin-top: 20px;
    line-height: 1.8;
}

.entry-body p {
    line-height: 1.8;
    min-height: 20px;
}

.entry-body img {
    display: block;
}

.entry-body figure {
    display: block;
    max-width: 660px;
    margin: 0 auto 90px;
}

.entry-body p a {
    color: #597ea6;
}

.entry-body p a:hover {
    text-decoration: underline;
}

.entry-body h1,
.entry-body h2,
.entry-body h3,
.entry-body h4,
.entry-body h5,
.entry-body h6,
.entry-body h7 {
    line-height: 1.7;
    font-weight: bold;
    margin-top: 1.5em;
    margin-bottom: 2em;
}

.entry-body h1 {
    font-size: 22px;
}
.entry-body h2 {
    font-size: 20px;
}
.entry-body h3 {
    font-size: 18px;
    background: #f2f2f2;
    padding: 15px 15px;
}
.entry-body h4 {
    font-size: 16px;
}
.entry-body h5 {
    font-size: 14px;
}
.entry-body h6 {
    font-size: 12px;
}
.entry-body h7 {
    font-size: 10px;
}

.entry-body table {
    font-size: 14px;
}

.entry-body th {
    border: 1px solid #f2f2f2;
    padding: 10px;
    background: #f7f7f7;
    text-align: center;
}
.entry-body td {
    border: 1px solid #f2f2f2;
    padding: 10px;
}

.entry-body ol {
    counter-reset: item;
}

.entry-body ol,
.entry-body ul {
    margin: 50px 0;
}

.entry-body ul li,
.entry-body ol li {
    position: relative;
    margin-bottom: 10px;
    font-size: 16px;
    padding: 0 0 0 12px;
    line-height: 1.6;
}

.entry-body ol li {
    padding-left: 20px;
}

.entry-body ul li::before {
    display: block;
    content: "";
    background: #000;
    background-size: 100%;
    width: 2px;
    height: 2px;
    position: absolute;
    border-radius: 8px;
    left: 0;
    top: 14px;
}

.entry-body ol li::before {
    counter-increment: item;
    content: counter(item) ".";
    position: absolute;
    left: 0;
    top: 0px;
}

.entry-body small {
    font-size: 12px;
}

.entry-body > *:first-child {
    margin-top: 0;
}

.entry-body iframe {
    max-width: 100%;
}

.entry-body strong,
.entry-body b {
    font-weight: bold;
}

.entry-body em {
    font-style: italic;
}

.entry-body blockquote {
    background: #f2f2f2;
    padding: 15px;
    margin-top: 20px;
}

.ql-align-center {
    text-align: center;
}
.ql-align-right {
    text-align: right;
}

.ql-video {
    width: 100%;
    height: 500px;
}

.entry-direction {
    border-top: 1px solid #cecece;
    padding-top: 20px;
}

.entry-direction ul {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
}

.entry-direction ul a {
    display: block;
    padding: 0 20px;
    position: relative;
    color: #597ea6;
}

.entry-direction ul a:hover {
    text-decoration: underline;
}

.entry-direction ul li:first-child a::before {
    content: "";
    position: absolute;
    left: 0;
    top: 50%;
    width: 8px;
    height: 8px;
    border-left: 1px solid #597ea6;
    border-bottom: 1px solid #597ea6;
    transform: translate(0, -50%) rotate(45deg);
}

.entry-direction ul li:last-child a::after {
    content: "";
    position: absolute;
    right: 0;
    top: 50%;
    width: 8px;
    height: 8px;
    border-top: 1px solid #597ea6;
    border-right: 1px solid #597ea6;
    transform: translate(0, -50%) rotate(45deg);
}

.entry-back a {
    position: relative;
    display: inline-block;
    padding-left: 15px;
    color: #597ea6;
}

.entry-back a:hover {
    text-decoration: underline;
}

.entry-back a::before {
    content: "";
    position: absolute;
    left: 0;
    top: 55%;
    width: 8px;
    height: 8px;
    border-left: 1px solid #597ea6;
    border-bottom: 1px solid #597ea6;
    transform: translate(0, -50%) rotate(45deg);
}

.entry-side {
    width: 230px;
}

.entry-side-download {
    border: 1px solid #707070;
    display: block;
    text-align: center;
    font-size: 16px;
    line-height: 1;
    padding: 20px;
    transition: all 0.25s ease;
}

.entry-side-download:hover {
    color: #fff;
    background: #707070;
}

.entry-sns {
    /*padding-bottom: 35px;*/
}

.entry-sns ul {
    display: flex;
    justify-content: flex-start;
    align-items: center;
    flex-wrap: wrap;
}

.entry-sns ul li {
    margin-right: 10px;
}

.entry-sns ul li a {
    display: block;
    transition: all 0.25s ease;
}

.entry-sns ul li a:hover {
    opacity: 0.7;
}

.entry-relate {
    padding: 20px 0;
    border-bottom: 1px solid #ccc;
}

.entry-relate-title {
    text-align: center;
    font-size: 16px;
    line-height: 1.3;
    margin-bottom: 20px;
}

.entry-relate-nodata {
    text-align: center;
    font-size: 14px;
    line-height: 1.6;
}

.entry-relate-list {
    padding-top: 10px;
}
.entry-relate-list > li:not(:first-child) {
    margin-top: 32px;
}

.entry-relate-item {
    display: flex;
    justify-content: space-between;
}

.entry-relate-item-image {
    width: 73px;
    height: 73px;
    position: relative;
    overflow: hidden;
}

.entry-relate-item-image img {
    max-width: 200%;
    width: auto;
    height: 100%;
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
}

.entry-relate-item-body {
    width: calc(100% - 80px);
}

.entry-relate-item .panel-item-category {
    margin-bottom: 5px;
}
.entry-relate-item .panel-item-category span {
    padding: 3px 6px;
    font-size: 10px;
}

.entry-relate-item .panel-item-date {
    font-size: 12px;
    margin-bottom: 2px;
}

.entry-relate-item .panel-item-title {
    font-size: 14px;
    line-height: 1.3;
    -webkit-line-clamp: 2;
}

/* -------------------- feature --------------------- */

.feature-wrapper {
    padding: 50px 30px 55px;
    overflow: hidden;
}

.feature {
}

@media screen and (min-width: 769px) {
    .feature-list {
        display: flex;
        flex-wrap: wrap;
    }

    .feature-list > li {
        width: calc(33.333% - 15px);
        margin-left: 22px;
    }
    .feature-list > li:nth-child(3n + 1) {
        margin-left: 0;
    }
    .feature .swiper-pagination {
        display: none;
    }
}

.feature-item {
    border-radius: 8px;
    border: 1px solid #d1d1d1;
    background: #fff;
    overflow: hidden;
}

.feature-item-image {
    width: 100%;
    height: 0;
    padding-bottom: 51%;
    position: relative;
    overflow: hidden;
}

.feature-item-image img {
    max-width: 100%;
    max-height: 100%;
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
}

.feature-item-body {
    padding: 30px;
}

.feature-item-category {
    display: flex;
    justify-content: flex-start;
    align-items: center;
    flex-wrap: wrap;
    margin-bottom: 10px;
}

.feature-item-category span {
    text-align: center;
    display: inline-block;
    color: #fff;
    font-size: 12px;
    line-height: 1.3;
    padding: 4px 15px;
    background: #333;
    border-radius: 20px;
    margin-right: 5px;
    margin-bottom: 5px;
}

.feature-item-date {
    font-size: 14px;
    line-height: 1.3;
    color: #808080;
    margin-bottom: 5px;
}

.feature-item-title {
    font-size: 18px;
    font-weight: bold;
    line-height: 1.5;
}

.feature-item-title.clamp3 {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    overflow: hidden;
    height: 85px;
}

.feature-item-text {
    font-size: 12px;
    color: #808080;
    line-height: 1.6;
    margin-top: 10px;
}

@media screen and (min-width: 769px) {
    .feature-item-category {
        display: -webkit-box;
        -webkit-box-orient: vertical;
        -webkit-line-clamp: 2;
        overflow: hidden;
        min-height: 60px;
    }
}

/* -------------------- table --------------------- */

.table-horizontal {
    font-size: 14px;
}

.table-horizontal thead th,
.table-horizontal thead td {
    background: #767676;
    color: #fff;
    line-height: 1.94;
    padding: 3px 4px;
    border-top: 1px solid #dbdbdb;
    border-right: 1px solid #dbdbdb;
    border-left: 1px solid #dbdbdb;
    text-align: center;
    white-space: nowrap;
}

.table-horizontal tbody th,
.table-horizontal tbody td {
    line-height: 1.75;
    padding: 6px 8px;
    background: #fff;
    border: 1px solid #dbdbdb;
}

.table-horizontal tbody th {
    text-align: center;
}

.table-horizontal tbody td.td-grouptitle {
    font-weight: 600;
    text-align: center;
    background: #dce3e8;
    color: #484848;
}

.table-horizontal.is-zebra tbody tr:nth-child(2n) th,
.table-horizontal.is-zebra tbody tr:nth-child(2n) td {
    background: #f2f2f2;
}

.table-vertical {
    border-top: 1px solid #dbdbdb;
}

.table-vertical th {
    text-align: left;
    padding: 16px;
    background: #f2f2f2;
    vertical-align: top;
    font-weight: 600;
    border-bottom: 1px solid #dbdbdb;
    color: #333;
    line-height: 1.6;
    text-align: left;
    min-width: 145px;
    vertical-align: middle;
}

.table-vertical td {
    text-align: left;
    padding: 16px 16px;
    vertical-align: top;
    border-bottom: 1px solid #dbdbdb;
    line-height: 1.6;
    color: #484848;
}

.table-horizontal td a,
.table-vertical td a {
    color: #0078c6;
}

.table-horizontal td a:hover,
.table-vertical td a:hover {
    text-decoration: underline;
}

.table-vertical td small {
    line-height: 1.3;
    display: inline-block;
    font-size: 12px;
}

/* modal ---------------------------------------*/

.modal-wrapper {
    display: none;
}

.modal {
    background: #fff;
}

.modal-inner {
    width: 100%;
    padding: 30px;
    background: #fff;
}

.modal-inner-manual {
    text-align: center;
}

.modal-inner-manual iframe {
    width: 600px;
    height: 500px;
}

.modal-inner-close {
    position: absolute;
    right: 10px;
    top: 10px;
}

/* form ---------------------------------------*/

.form-area .submit {
    text-align: center;
}

.form-select {
    width: 100%;
    padding: 9px 13px;
    font-size: 14px;
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
    border: 1px solid #f2f2f2;
    background: url("../img/common/select.svg") no-repeat right 10px top 50%
        #f2f2f2;
    background-size: 11px;
    border-radius: 8px;
    outline: none;
    color: #b3b3b3;
}

.form-select.is-noselect {
    color: #b3b3b3;
}

.form-date {
    padding: 9px 13px;
    font-size: 14px;
    background: #f2f2f2;
    color: #b3b3b3;
    border: none;
    box-sizing: border-box;
    -webkit-appearance: none;
    outline: none;
    border-radius: 8px;
    line-height: 1;
    background: url("../img/common/select.svg") no-repeat right 10px top 50%
        #f2f2f2;
    background-size: 11px;
}

.is-selected {
    color: #000;
}

select::-ms-expand {
    display: none;
}

.form-text {
    font-size: 16px;
    padding: 10px 13px;
    background: #f2f2f2;
    border: 1px solid #f2f2f2;
    width: 100%;
    box-sizing: border-box;
    -webkit-appearance: none;
    outline: none;
    border-radius: 8px;
}

.form-radio {
    display: inline-block;
    line-height: 1;
    margin-right: 5px;
    font-size: 14px;
    position: relative;
}

.form-radio label {
    box-sizing: border-box;
    cursor: pointer;
    display: inline-block;
    line-height: 1.4;
    min-height: 23px;
    margin: 0px 0;
    padding: 3px 0 0 25px;
    position: relative;
    vertical-align: top;
}

.form-radio input[type="radio"] {
    position: absolute;
    left: 0px;
    top: 0px;
    width: 1px;
    height: 1px;
    overflow: hidden;
    opacity: 0;
}

.form-radio label::before {
    display: block;
    content: "";
    border: 1px solid #aaa;
    border-radius: 50%;
    width: 20px;
    height: 20px;
    position: absolute;
    left: 0;
    top: 50%;
    transform: translate(0, -50%);
}

.form-radio input:checked + label::after {
    display: block;
    content: "";
    background: #2a619b;
    border-radius: 50%;
    width: 14px;
    height: 14px;
    position: absolute;
    left: 4px;
    top: 50%;
    transform: translate(0, -50%);
}

.form-radio input:disabled + label {
    opacity: 0.7;
}

.form-checkbox {
    display: inline-block;
    line-height: 1;
    margin-right: 5px;
    font-size: 14px;
    position: relative;
}

.form-checkbox label {
    box-sizing: border-box;
    cursor: pointer;
    display: inline-block;
    line-height: 1.4;
    min-height: 23px;
    margin: 0px 0;
    padding: 3px 0 0 30px;
    position: relative;
    vertical-align: top;
}

.form-checkbox input[type="checkbox"] {
    position: absolute;
    left: 0px;
    top: 0px;
    width: 1px;
    height: 1px;
    overflow: hidden;
    opacity: 0;
}

.form-checkbox label::before {
    display: block;
    content: "";
    border: none;
    background: #f2f2f2;
    border-radius: 2px;
    width: 20px;
    height: 20px;
    position: absolute;
    left: 0;
    top: 50%;
    transform: translate(0, -50%);
}

.form-checkbox input:checked + label::after {
    display: block;
    content: "";
    width: 5px;
    height: 8px;
    border-right: 2px solid #333;
    border-bottom: 2px solid #333;
    position: absolute;
    left: 7px;
    top: 45%;
    transform: translate(0, -50%) rotate(40deg);
}

.form-checkbox input:disabled + label {
    opacity: 0.7;
}

.form-textarea {
    padding: 13px 5px;
    border: 1px solid #999;
    width: 100%;
    box-sizing: border-box;
    height: 80px;
    -webkit-appearance: none;
    outline: none;
    border-radius: 0;
}

::placeholder {
    color: #ccc;
}

.toggle-switch {
    position: relative;
    width: 60px;
    height: 30px;
    margin: auto;
    display: inline-block;
}

.toggle-input {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    z-index: 5;
    opacity: 0;
    cursor: pointer;
}

.toggle-switch label {
    width: 60px;
    height: 30px;
    background: #ccc;
    position: relative;
    display: inline-block;
    border-radius: 30px;
    transition: 0.1s;
    box-sizing: border-box;
}

.toggle-switch label::after {
    content: "";
    position: absolute;
    width: 30px;
    height: 30px;
    border-radius: 100%;
    left: 0;
    top: 0;
    z-index: 2;
    background: #fff;
    box-shadow: 0 0 5px rgba(0, 0, 0, 0.2);
    transition: 0.1s;
}

.toggle-input:checked + label {
    background-color: #4bd865;
}

.toggle-input:checked + label::after {
    left: 30px;
}

.must {
    color: #aa0000;
}

/* accordion ---------------------------------------*/

.accordion {
}

.accordion-title {
    position: relative;
    display: inline-block;
    padding-right: 50px;
    cursor: pointer;
}

.accordion-title:hover {
    color: #2a619b;
    text-decoration: underline;
}

.accordion-title::after {
    display: block;
    content: "";
    border-bottom: 3px solid #2a619b;
    border-right: 3px solid #2a619b;
    width: 10px;
    height: 10px;
    margin-top: -17px;
    position: absolute;
    right: 10px;
    top: 50%;
    transform: rotate(45deg);
    transition: all 0.25s ease;
}

.accordion-title.is-open::after {
    transform: rotate(225deg);
}

.accordion-body {
    display: none;
}

/* search result ---------------------------------------*/

.searchresult-title {
    font-size: 32px;
    text-align: center;
    line-height: 1.5;
    padding: 100px 0 0px;
}

.searchresult-search {
    max-width: 565px;
    margin: 0 auto 55px;
    position: relative;
}

.searchresult-search input {
    background: #f2f2f2;
    font-size: 16px;
    line-height: 1.6;
    padding: 12px 15px;
    border: none;
    width: 100%;
    padding-right: 70px;
}

.searchresult-search button {
    background: none;
    padding: 0;
    border: none;
    cursor: pointer;
    position: absolute;
    right: 0px;
    top: 0;
    height: 100%;
    width: 70px;
    text-align: center;
    background: #808080;
}

.searchresult-search button:hover {
    opacity: 0.7;
}

.searchresult-list-wrapper {
}

.searchresult-list {
    padding-bottom: 30px;
}

.searchresult-list > li {
    margin-top: 40px;
}

.searchresult-item {
    display: flex;
    justify-content: space-between;
}

.searchresult-item-image {
    width: 146px;
    height: 92px;
    border-radius: 8px;
    overflow: hidden;
}

.searchresult-item-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.searchresult-item-body {
    width: calc(100% - 146px);
    padding-left: 20px;
}

.searchresult-item-date {
    font-size: 14px;
    line-height: 1.5;
    color: #808080;
}

.searchresult-item-title {
    font-size: 18px;
    line-height: 1.6;
    color: #333333;
    font-weight: bold;
    display: block;
}

.searchresult-item-category {
    font-size: 14px;
    line-height: 1.5;
    color: #808080;
    display: inline-block;
    text-decoration: underline;
}

/* ハートアイコン */
.likeButton {
    cursor: pointer;
}

.likeButton .border {
    fill: white;
}

.likeButton .explosion {
    -webkit-transform-origin: 250px 250px;
    transform-origin: 250px 250px;
    -webkit-transform: scale(0.02);
    transform: scale(0.02);
    stroke: #dd4688;
    fill: none;
    opacity: 0;
    stroke-width: 1;
    transform-origin: 250px 250px;
}

.likeButton .particleLayer {
    opacity: 0;
}

.likeButton .particleLayer circle {
    opacity: 0;
    -webkit-transform-origin: 250px 250px;
    transform-origin: 250px 250px;
}

.likeButton .heart {
    fill: rgba(6, 6, 6, 0.24);
    -webkit-transform: scale(0.8);
    transform: scale(0.8);
    -webkit-transform-origin: 250px 250px;
    transform-origin: 250px 250px;
}

.likeButton.clicked .explosion {
    -webkit-animation: explosionAnime 800ms;
    animation: explosionAnime 800ms;
    -webkit-animation-fill-mode: forwards;
    animation-fill-mode: forwards;
}

.likeButton.clicked .heart {
    -webkit-animation: heartAnime 800ms;
    animation: heartAnime 800ms;
    -webkit-animation-fill-mode: forwards;
    animation-fill-mode: forwards;
}

.likeButton.clicked .particleLayer {
    -webkit-animation: particleLayerAnime 800ms;
    animation: particleLayerAnime 800ms;
    -webkit-animation-fill-mode: forwards;
    animation-fill-mode: forwards;
}

