    .feature-item-title.clamp3 {
        height: 70px;
    }

    .feature-item-text {
    }

    .feature.swiper-container-horizontal > .swiper-pagination-bullets {
        bottom: 0;
    }

    .feature.swiper-container-horizontal
        > .swiper-pagination-bullets
        > .swiper-pagination-bullet {
        width: 20px;
        height: 20px;
        background: #fff;
        border: 1px solid #333;
        margin: 0 15px;
    }
    .feature.swiper-container-horizontal
        > .swiper-pagination-bullets
        > .swiper-pagination-bullet-active {
        background: #333;
    }

    /* table ---------------------------------------*/

    .table-wrapper {
        margin-bottom: 55px;
    }

    .table-horizontal,
    .table-horizontal tbody,
    .table-horizontal tr,
    .table-horizontal th,
    .table-horizontal td {
        display: block;
        width: 100%;
    }

    .table-horizontal th,
    .table-horizontal td {
        font-size: 16px;
        border: none;
    }

    .table-horizontal th {
        padding: 18px 20px 18px 20px;
    }

    .table-horizontal td {
        padding: 25px 20px 25px 20px;
    }

    .table-sp-scroll {
        overflow: auto;
        width: calc(100% + 30px);
        margin: 0 -15px;
        padding-left: 15px;
    }

    .table-sp-scroll table {
        min-width: 450px;
    }

    /* modal ---------------------------------------*/

    .modal-wrapper {
        display: none;
    }

    .modal {
        padding: 60px 10px 20px;
    }

    .modal-inner-close {
        width: 320px;
        max-width: 100%;
        margin: 30px auto;
    }

    /* form ---------------------------------------*/

    .form-area .submit {
    }

    .form-select {
        padding: 11px 15px;
        font-size: 16px;
    }

    .form-date {
        padding: 11px 15px;
        font-size: 16px;
    }

    .form-text {
        font-size: 16px;
        padding: 15px 15px;
    }

    .form-checkbox {
        display: inline-block;
        line-height: 1;
        margin-right: 5px;
        font-size: 15px;
        position: relative;
    }

    .form-checkbox label {
        box-sizing: border-box;
        cursor: pointer;
        display: inline-block;
        line-height: 1.4;
        min-height: 23px;
        margin: 0px 0;
        padding: 0px 0 0 38px;
        position: relative;
        vertical-align: top;
    }

    .form-checkbox input[type="checkbox"] {
        position: absolute;
        left: 0px;
        top: 0px;
        width: 1px;
        height: 1px;
        overflow: hidden;
        opacity: 0;
    }

    .form-checkbox label::before {
        display: block;
        content: "";
        border: none;
        background: #f2f2f2;
        border-radius: 8px;
        width: 30px;
        height: 30px;
        position: absolute;
        left: 0;
        top: 50%;
        transform: translate(0, -50%);
    }

    .form-checkbox input:checked + label::after {
        display: block;
        content: "";
        width: 7px;
        height: 10px;
        border-right: 2px solid #333;
        border-bottom: 2px solid #333;
        position: absolute;
        left: 11px;
        top: 45%;
        transform: translate(0, -50%) rotate(40deg);
    }

    /* search result ---------------------------------------*/

    .searchresult-title {
        font-size: 26px;
        padding: 60px 0 0px;
    }

    .searchresult-search {
        margin: 0 auto 45px;
    }
    .searchresult-search input {
        padding-right: 50px;
    }
    .searchresult-search button {
        width: 50px;
    }

    .searchresult-search button:hover {
        opacity: 0.7;
    }
    .searchresult-list-wrapper {
    }
    .searchresult-list {
        padding-bottom: 30px;
    }

    .searchresult-list > li {
        margin-top: 17px;
        padding: 13px;
        border: 1px solid #b3b3b3;
        border-radius: 8px;
    }

    .searchresult-item {
    }

    .searchresult-item-image {
        width: 21vw;
        height: 13vw;
        border-radius: 4px;
    }

    .searchresult-item-image img {
    }

    .searchresult-item-body {
        width: calc(100% - 21vw);
        padding-left: 10px;
    }

    .searchresult-item-date {
        font-size: 12px;
    }
    .searchresult-item-title {
        font-size: 16px;
        margin-bottom: 5px;
    }
    .searchresult-item-category {
        font-size: 12px;
    }
}

