/* swiper 独自設定 */

/* dots */

.swiper-pagination{
	width:100%;
	bottom:0px;
	line-height: 1.0;
}

.swiper-pagination-bullet{
	background: #ccc;
	opacity:1;
	margin:0 4px;
	outline: none;
}

.swiper-pagination-bullet-active{
	background: #747474;
	outline: none;
}


/* arrow */

.swiper-button-prev,
.swiper-container-rtl .swiper-button-next{
	background-image:url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2027%2044'%3E%3Cpath%20d%3D'M0%2C22L22%2C0l2.1%2C2.1L4.2%2C22l19.9%2C19.9L22%2C44L0%2C22L0%2C22L0%2C22z'%20fill%3D'%23cccccc'%2F%3E%3C%2Fsvg%3E");
	left:10px;
	right:auto;
	outline: none;
}

.swiper-button-next,
.swiper-container-rtl .swiper-button-prev{
	background-image:url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2027%2044'%3E%3Cpath%20d%3D'M27%2C22L27%2C22L5%2C44l-2.1-2.1L22.8%2C22L2.9%2C2.1L5%2C0L27%2C22L27%2C22z'%20fill%3D'%23cccccc'%2F%3E%3C%2Fsvg%3E");
	right:10px;
	left:auto;
	outline: none;
}

.swiper-button-next, .swiper-button-prev {
	position: absolute;
	top: 50%;
	width: 13px;
	height: 22px;
	margin-top: -11px;
	z-index: 10;
	cursor: pointer;
	background-size: 13px 22px;
	background-position: center;
	background-repeat: no-repeat;
	transition: all .1s ease;
	outline: none;
}

.swiper-button-next:hover, .swiper-button-prev:hover {
	opacity:0.5;
}

.swiper-slide{width:0px;}

@charset "UTF-8";


.indexnews{padding: 30px 30px 40px;}

.indexcontents{padding: 44px 30px;}

.indexcontents-list{
	display:flex;
	justify-content:space-between;
	flex-wrap: wrap;
	gap:20px;
}

.indexcontents-list > li{
	width: calc(33.3333% - 20px);
}

.indexcontents-list > li:nth-child(3n + 1){margin-left: 0;}

.indexcontents-list-item{
	display: block;
	text-align:center;
	border:1px solid #ccc;
	border-radius: 8px;
	padding: 20px 15px 20px;
	transition: all .25s ease;
	height: 100%;
	overflow: hidden;
	position: relative;
}

.indexcontents-list-item::after{
	content: '';
	display: block;
	position: absolute;
	right: 0;
	bottom: 0;
	border-left: 35px transparent solid;
	border-top: 35px transparent solid;
	border-bottom: 35px #808080 solid;
	transition: all .25s ease;
}

.indexcontents-list-item:hover{
	background-color: #fafafa;
	box-shadow: 0px 0px 10px rgba(0,0,0,0.1);
}

.indexcontents-list-item:hover::after{border-bottom: 35px #333 solid;}

.indexcontents-item-image{
	position:relative;
	height: 100px;
}

.indexcontents-item-image img{
	position:absolute;
	left:50%;
	top:0%;
	transform:translate(-50%,0);
}

.indexcontents-item-text{
	text-align:center;
	font-size: 12px;
	line-height: 1.8;
	margin-top: 0px;
	color: #808080;
}

.indexcontents-list > li.is-upline img{ width: 204px; }
.indexcontents-list > li.is-makenewmagazine img{width:100%;}
.indexcontents-list > li.is-panasonicstore img{width:260px;}
.indexcontents-list > li.is-youtube img{ width: 180px;top: 20px;}
.indexcontents-list > li.is-twitter img{ width: 60px; top: 10px;}
.indexcontents-list > li.is-instagram img{ width: 67px; top: 10px;}



.indexcontents-item-bottom{
	position:absolute;
	left: 0;
	bottom: 20px;
	width: 100%;
	text-align:center;
}

.indexcontents-list-item .arrow{
	content: '';
	display: block;
	position: absolute;
	right: 0;
	bottom: 0;
	width: 20px;
	height: 20px;
	z-index: 5;
}

.indexcontents-list-item .arrow::before{
	display:block;
	content:'';
	background:#fff;
	background-size:100%;
	width:4px;
	height:1px;
	position:absolute;
	left: 11px;
	top:8px;
	transform:translate(0,-50%) rotate(45deg);
}

.indexcontents-list-item .arrow::after{
	display:block;
	content:'';
	background:#fff;
	background-size:100%;
	width:10px;
	height:1px;
	position:absolute;
	left: 5px;
	top:10px;
	transform:translate(0,-50%);
}



/* small pc */
@media screen and (min-width: 769px) and (max-width: 1200px){


}



@media screen and (max-width: 768px){


	.indexnews{padding: 30px 20px 40px;}
	.indexcontents{padding: 45px 20px 20px;}

	.indexcontents-list{
		display: block;
		padding: 0 10px;
	}

	.indexcontents-list > li{
		width: auto;
		margin: 0 0 30px 0px;
	}

	.indexcontents-list-item{
		border-radius:5px;
		height: auto;
		padding-bottom: 20px
	}

	.indexcontents-item-image{
		height:auto;
		margin-bottom: 10px
	}

	.indexcontents-item-image img{
		position:relative;
		left: 0;
		transform: translate(0,0);
	}

	.indexcontents-list > li.is-upline img{width: 240px}
	.indexcontents-list > li.is-makenewmagazine img{width:280px;}
	.indexcontents-list > li.is-panasonicstore img{width:260px;}
	.indexcontents-list > li.is-youtube img{ width: 180px;top: 0;}
	.indexcontents-list > li.is-twitter img{ width: 60px;top: 0;}
	.indexcontents-list > li.is-instagram img{ width: 67px;top: 0;}

	.indexcontents-item-text{
		font-size: 13px;
		line-height: 1.7;
		margin-top: 15px;
	}

	.indexcontents-item-bottom{
		bottom: 0px;
		position:relative;
		margin-top: 15px
	}




}

