			$('body, html').animate({scrollTop:position}, speed, 'swing');
			return false;
		});
	};

	//デバイス判定（ロード時とリサイズ時）
	$(window).on('load resize',function(){
		(window.innerWidth > BREAKPOINT)?changeToPc():changeToSp();
	});


	//pcに切り替わった時の処理
	function changeToPc(){
		if(deviceType != "pc"){
			deviceType = "pc";
			//spメニューが開いていた時のクリア処理
			$('.gnav').attr('style','');
			$('#openmenu').removeClass('open');
			spbnr3sliderBreak();
		}
	}


	//spに切り替わった時の処理
	function changeToSp(){
		if(deviceType != "sp"){
			//spのみのスライダースタート
			spbnr3sliderStart();
			deviceType = "sp";
		}
	}


	//spのハンバーガーメニュー
	var scrollpos;
	$('#openmenu').click(function(ev){
		ev.preventDefault();
		if($(this).hasClass('is-open')){
			$('.gnav').removeClass('is-active');
			$('body').removeClass('bodyfixed').css({'top': 0});
			 window.scrollTo( 0 , scrollpos );
			$(this).removeClass('is-open');
			$('.overlay').remove();
		} else {
			scrollpos = $(window).scrollTop();
			$('.gnav').addClass('is-active');
			$('body').addClass('bodyfixed').css({"top": -scrollpos});
			$('body').append('<div class="overlay"></div>');
			$('.overlay').height($(window).height()).fadeIn(200);
			$(this).addClass('is-open');
		}
	});
	$('.gnav a').click(function(){
		if($(window).innerWidth() < 768){
			var linktarget = $(this).attr('href');
			if(linktarget.slice(0,1) == "#"){
				//グロナビ閉じる
				$('.gnav').removeClass('is-active');
				$('body').removeClass('bodyfixed').css({'top': 0});
				 window.scrollTo( 0 , scrollpos );
				$('#openmenu').removeClass('is-open');
				$('.overlay').remove();
				//スクロールさせる
				var position = $(linktarget).offset().top - 50;
				$('body,html').animate({scrollTop:position},500,'swing');
			}
		}
	});



	//新着スライダー（spのみ）
	var spbnr3slider;
	var isspbnr3slider = false;
	function spbnr3sliderStart(){
		$('.feature-list').addClass('swiper-wrapper');
		$('.feature-list li').addClass('swiper-slide');
		isspbnr3slider = true;

		spbnr3slider = new Swiper ('.feature', {
//			loop: true,
			speed: 600,
			spaceBetween: 10,
			slidesPerView: 1,
			centeredSlides:true,
			direction: 'horizontal',
			watchOverflow: true,
			effect: 'slide',
			// スライダーの自動再生
			autoplay: {
				delay: 7000,
				stopOnLast: false,
				disableOnInteraction: false
			},
			// ページネーションを表示する場合
			pagination: {
				el: '.feature .swiper-pagination',
				clickable:true
			}
		});
	}
	function spbnr3sliderBreak(){
		if($('.feature-list').length > 0){
			$('.feature-list').removeClass('swiper-wrapper');
			$('.feature-list li').removeClass('swiper-slide');
			spbnr3slider.destroy();
			console.log('destroy');
		}
	}


	//modal
	$(".modal-btn").colorbox({
		fixed:true,
		maxWidth:'80%',
		maxHeight:'80%',
		inline:true
	});
	$(document).on('cbox_complete',function(){
		$('#cboxClose').fadeIn();
	});
	$(document).on('cbox_closed',function(){
		$('#cboxClose').hide();
	});
	$('.modal-inner-close').click(function () {
		$.colorbox.close();
	});


	//ブログ詳細
	//table
	$('.entry-body table').each(function(index, element){
		$(this).wrap('<div class="table-wrapper"><div class="table-scroll">');
	});


	//フォーム処理
	$('.form-select').change(function(){
		var $this = $(this);
		if($this.val()==""){
			$this.removeClass('is-selected');
		} else {
			$this.addClass('is-selected');
		}
	});
	$(document).on('change','.form-date-ready',function(){
		var $this = $(this);
		if($this.val()=="YYYY/MM/DD"){
			$this.removeClass('is-selected');
		} else {
			$this.addClass('is-selected');
		}
	});

	//トップのメインメニューのspクリック
	$('.indexmenu-list > li').click(function(){
		var $this = $(this);
		if(deviceType == "sp"){
			var target = $this.find('a').attr('href');
			location.href = target;
		}
	});

});


